INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein archivierter Bericht nur für Audits relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für Referenz nützlich"}, {"text": "Ja", "correct": false, "because": "Mehrzweck"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Format wähle ich für einen archivierten Bericht?', 3, '[{"text": "PDF", "correct": true, "because": "Universell lesbar"}, {"text": "Word", "correct": false, "because": "Bearbeitbar"}, {"text": "TXT", "correct": false, "because": "Keine Formatierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die Archivierung eines Berichts?', 5, '[{"text": "Nachverfolgbarkeit", "correct": true, "because": "Historie bleibt erhalten"}, {"text": "Rechtssicherheit", "correct": true, "because": "Beweis bei Streit"}, {"text": "Schnelle Bearbeitung", "correct": false, "because": "Nicht primär"}, {"text": "Hohe Auflösung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Archivierung schützt Daten. b) Sie ersetzt Backups.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Backups sind separat"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Berichtarchivierung?', 4, '[{"text": "Zugriffsrechte", "correct": false, "because": "Sicherheit entscheidend"}, {"text": "Speicherort", "correct": false, "because": "Nachvollziehbarkeit"}, {"text": "Papierfarbe", "correct": true, "because": "Digital irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Bericht immer physisch archiviert wird?', 2, '[{"text": "Nein", "correct": true, "because": "Digital üblich"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches System nutze ich zur Berichtarchivierung?', 3, '[{"text": "DMS", "correct": true, "because": "Dokumentenmanagement"}, {"text": "E-Mail", "correct": false, "because": "Unstrukturiert"}, {"text": "Notepad", "correct": false, "because": "Keine Verwaltung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen eine Archivierung effektiv?', 5, '[{"text": "Versionierung", "correct": true, "because": "Änderungen nachvollziehbar"}, {"text": "Metadaten", "correct": true, "because": "Schnellsuche"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Netzwerk-spezifisch"}, {"text": "Farbcodierung", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Archivierung ist gesetzlich Pflicht. b) Sie ist nur für große Projekte. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch kleine Projekte"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) oft richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Berichtarchivierung?', 4, '[{"text": "Speicherplatz", "correct": false, "because": "Grundvoraussetzung"}, {"text": "Zugriffskontrolle", "correct": false, "because": "Sicherheit"}, {"text": "Drucker", "correct": true, "because": "Digital ausreichend"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Archivierung gleich Backup?', 2, '[{"text": "Nein", "correct": true, "because": "Unterschiedliche Zwecke"}, {"text": "Ja", "correct": false, "because": "Backup ist Wiederherstellung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zur Berichtarchivierung?', 4, '[{"text": "Dokument-ID", "correct": true, "because": "Eindeutigkeit"}, {"text": "Speicherort", "correct": true, "because": "Zugriff"}, {"text": "Monitorgröße", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Archivierung nur für Papier ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Digital dominierend"}, {"text": "Ja", "correct": false, "because": "Nicht mehr aktuell"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Berichtarchivierung?', 3, '[{"text": "Langzeitverfügbarkeit", "correct": true, "because": "Zugriff über Jahre"}, {"text": "Schnelle Erstellung", "correct": false, "because": "Nicht primär"}, {"text": "Farbanpassung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Archivierung braucht Metadaten. b) Sie ersetzt Projektmanagement.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "PM separat"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat eine schlechte Archivierung?', 5, '[{"text": "Datenverlust", "correct": true, "because": "Keine Wiederherstellung"}, {"text": "Schwer auffindbar", "correct": true, "because": "Fehlende Struktur"}, {"text": "Hohe Leistung", "correct": false, "because": "Kein Nachteil"}, {"text": "Schnelle Suche", "correct": false, "because": "Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Archivierung unwichtig?', 3, '[{"text": "Sicherheit", "correct": false, "because": "Schutz entscheidend"}, {"text": "Format", "correct": false, "because": "Lesbarkeit"}, {"text": "Schriftgröße", "correct": true, "because": "Digital anpassbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Dient Archivierung nur der Dokumentation?', 3, '[{"text": "Nein", "correct": true, "because": "Auch rechtlich relevant"}, {"text": "Ja", "correct": false, "because": "Mehrzweck"}]'),
('00000000-0000-0000-0000-000Alcohol0000', 'Kannst du dich erinnern, ob Archivierung automatisiert sein muss?', 2, '[{"text": "Nein", "correct": true, "because": "Manuell möglich"}, {"text": "Ja", "correct": false, "because": "Flexibel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature ist für die Archivierung entscheidend?', 4, '[{"text": "Suchfunktion", "correct": true, "because": "Schneller Zugriff"}, {"text": "Hohe Auflösung", "correct": false, "because": "Bild-spezifisch"}, {"text": "Manuelle Eingabe", "correct": false, "because": "Nicht primär"}]');
